{
  "story": "Start with a Noise canvas and a fixed Prompt for an apple. Follow the trained Denoiser, Predicted noise, and Sampler update. Compare the Intermediate canvas with the Final image to discover what repeated updates accomplish. This schematic uses pixel-space noise prediction, not latent decoding.",
  "aha": {
    "stateId": "final-image",
    "observation": "The image emerges through repeated noise-guided updates to the same canvas; the Denoiser's noise prediction is not itself the image."
  },
  "layout": {
    "preset": "stepper-states",
    "width": 640
  },
  "parts": [
    {
      "id": "sampling-rail",
      "kind": "step-rail",
      "presentation": "Place below the story and above the picture. Show the active evidence stage and completed trace; stages represent states, not elapsed time.",
      "bind": {
        "active": "state.id",
        "items": "variant.states"
      }
    },
    {
      "id": "sampling-picture",
      "kind": "fixed-picture",
      "presentation": "Use the canonical pipeline composition with a feedback link. Keep named regions fixed and highlight bound active regions. Snapshot regions provide schematic comparisons.",
      "bind": {
        "active": "state.active",
        "links": "variant.links",
        "regions": "variant.regions"
      }
    },
    {
      "id": "sampling-callout",
      "kind": "active-callout",
      "presentation": "Anchor beside the active region without covering labels. Identify the mechanism here; reserve numerical values for readouts.",
      "bind": {
        "target": "state.calloutRegion",
        "text": "state.sentence",
        "reason": "state.why"
      }
    },
    {
      "id": "sampling-readouts",
      "kind": "value-readout",
      "presentation": "Place beneath the picture, with Status last. Counts use whole completed updates, referenced to the initial Noise canvas; no rounding applies.",
      "bind": {
        "values": "state.readouts"
      }
    }
  ],
  "controls": [
    {
      "id": "stage",
      "kind": "index",
      "items": "variant.states",
      "label": "Sampling stage",
      "presentation": "Navigation only; parameter-control budget is zero. Default: first state. Bounds: first through last state; increment: one state. Use Previous and Next, retaining names when disabled. Every state persists until learner action. Provide accessible names, visible focus, and keyboard operation. Reference capture: final-image."
    },
    {
      "id": "reset",
      "kind": "reset",
      "label": "Reset",
      "presentation": "Restore the first state and all defaults, including the same illustrative starting noise. Provide an accessible name, visible focus, and keyboard operation."
    }
  ],
  "data": {
    "variants": [
      {
        "label": "Balanced — schematic noise-predicting pixel-space sampler",
        "regions": [
          {
            "id": "prompt",
            "label": "Prompt",
            "values": [
              "A red apple on a white background",
              "Held fixed throughout"
            ]
          },
          {
            "id": "noise-canvas",
            "label": "Noise canvas",
            "values": [
              "Starting snapshot: random pixel noise",
              "No clean reference image is supplied"
            ]
          },
          {
            "id": "denoiser",
            "label": "Denoiser",
            "values": [
              "Inputs: current canvas, noise level, Prompt",
              "Trained weights remain fixed"
            ]
          },
          {
            "id": "predicted-noise",
            "label": "Predicted noise",
            "values": [
              "Estimated noise in the current canvas",
              "Not a finished apple image"
            ]
          },
          {
            "id": "sampler-update",
            "label": "Sampler update",
            "values": [
              "Combines current canvas, prediction, and schedule",
              "Produces the next, less-noisy canvas"
            ]
          },
          {
            "id": "intermediate-canvas",
            "label": "Intermediate canvas",
            "values": [
              "Comparison snapshot: coarse apple structure",
              "Residual noise remains"
            ]
          },
          {
            "id": "final-image",
            "label": "Final image",
            "values": [
              "Final snapshot: recognizable apple",
              "Result of successive canvas updates"
            ]
          }
        ],
        "links": [
          {
            "from": "prompt",
            "to": "denoiser",
            "label": "Guides every prediction"
          },
          {
            "from": "noise-canvas",
            "to": "denoiser",
            "label": "First current canvas"
          },
          {
            "from": "denoiser",
            "to": "predicted-noise",
            "label": "Predict noise"
          },
          {
            "from": "predicted-noise",
            "to": "sampler-update",
            "label": "Guide the update"
          },
          {
            "from": "noise-canvas",
            "to": "sampler-update",
            "label": "Starting canvas"
          },
          {
            "from": "sampler-update",
            "to": "intermediate-canvas",
            "label": "Early update"
          },
          {
            "from": "intermediate-canvas",
            "to": "denoiser",
            "label": "Repeat with updated canvas and lower noise level"
          },
          {
            "from": "sampler-update",
            "to": "final-image",
            "label": "After the last update"
          }
        ],
        "states": [
          {
            "id": "start",
            "label": "Start with noise",
            "short": "Noise",
            "sentence": "The Noise canvas starts as random pixels; the Prompt describes an apple but supplies no clean image.",
            "why": "The starting sample is held fixed throughout this walkthrough, so each later snapshot belongs to the same generation.",
            "active": [
              "noise-canvas",
              "prompt"
            ],
            "calloutRegion": "noise-canvas",
            "readouts": [
              {
                "id": "completed-updates",
                "label": "Completed updates",
                "value": "0"
              },
              {
                "id": "assumptions",
                "label": "Assumptions",
                "value": "Schematic pixel-space sampler; trained weights, starting noise, Prompt, and decreasing noise schedule are fixed."
              },
              {
                "id": "scope",
                "label": "Scope",
                "value": "Four illustrative updates; these snapshots do not simulate image quality."
              },
              {
                "id": "status",
                "label": "Status",
                "value": "Ready to predict noise in the starting canvas."
              }
            ]
          },
          {
            "id": "predict",
            "label": "Predict noise",
            "short": "Predict",
            "sentence": "The Denoiser uses the current canvas, noise level, and Prompt to produce Predicted noise.",
            "why": "Predicted noise estimates corruption in the canvas; it is not the image that should be displayed.",
            "active": [
              "prompt",
              "denoiser",
              "predicted-noise"
            ],
            "calloutRegion": "predicted-noise",
            "readouts": [
              {
                "id": "completed-updates",
                "label": "Completed updates",
                "value": "0"
              },
              {
                "id": "canvas-state",
                "label": "Canvas state",
                "value": "Unchanged; making a prediction has not yet updated the pixels."
              },
              {
                "id": "invariant",
                "label": "Held fixed",
                "value": "Prompt and trained weights"
              },
              {
                "id": "status",
                "label": "Status",
                "value": "Noise prediction is ready for the Sampler update."
              }
            ]
          },
          {
            "id": "first-update",
            "label": "Update the canvas",
            "short": "Update",
            "sentence": "The Sampler update uses Predicted noise and the schedule to produce the Intermediate canvas.",
            "why": "Compare the prediction with the canvas: one estimates noise, while the other retains image content and becomes less noisy.",
            "active": [
              "predicted-noise",
              "sampler-update",
              "intermediate-canvas"
            ],
            "calloutRegion": "sampler-update",
            "readouts": [
              {
                "id": "completed-updates",
                "label": "Completed updates",
                "value": "1"
              },
              {
                "id": "canvas-state",
                "label": "Canvas state",
                "value": "Coarse structure with substantial residual noise"
              },
              {
                "id": "invariant",
                "label": "Held fixed",
                "value": "Prompt and trained weights"
              },
              {
                "id": "status",
                "label": "Status",
                "value": "The updated canvas, not the noise prediction, continues through the process."
              }
            ]
          },
          {
            "id": "repeat",
            "label": "Repeat the same mechanism",
            "short": "Repeat",
            "sentence": "Two more prediction-and-update cycles refine the same canvas at successively lower noise levels.",
            "why": "Each Denoiser call receives the latest canvas; the Prompt and trained weights stay fixed while the canvas changes.",
            "active": [
              "intermediate-canvas",
              "denoiser",
              "predicted-noise",
              "sampler-update"
            ],
            "calloutRegion": "denoiser",
            "readouts": [
              {
                "id": "completed-updates",
                "label": "Completed updates",
                "value": "3"
              },
              {
                "id": "canvas-state",
                "label": "Canvas state",
                "value": "Refined structure with less residual noise"
              },
              {
                "id": "invariant",
                "label": "Held fixed",
                "value": "Prompt and trained weights"
              },
              {
                "id": "status",
                "label": "Status",
                "value": "The feedback link reuses the updated canvas; it does not restart from fresh noise."
              }
            ]
          },
          {
            "id": "final-image",
            "label": "Inspect the result",
            "short": "Image",
            "sentence": "The Final image comes from repeated noise-guided updates to the same canvas, not from displaying a single noise prediction.",
            "why": "Compare the Noise canvas, Intermediate canvas, and Final image: useful structure emerges as the sampler progressively reduces noise.",
            "active": [
              "noise-canvas",
              "intermediate-canvas",
              "final-image"
            ],
            "calloutRegion": "final-image",
            "readouts": [
              {
                "id": "completed-updates",
                "label": "Completed updates",
                "value": "4"
              },
              {
                "id": "canvas-state",
                "label": "Canvas state",
                "value": "Final image in this schematic run"
              },
              {
                "id": "invariant",
                "label": "Held fixed",
                "value": "Prompt and trained weights"
              },
              {
                "id": "status",
                "label": "Status",
                "value": "Generation is complete; this evidence remains visible until you navigate or reset."
              }
            ]
          }
        ]
      }
    ]
  }
}
